insert into public.species (slug,name,latin,category_id,kind,difficulty,temperament,description,facts,keywords,is_rare,status) values
('gambusia-affinis','Sivrisinek Balığı','Gambusia affinis','canli-doguranlar','fish','Kolay','Hareketli, zaman zaman hırçın','Dayanıklı ve yüzeye yakın yaşayan küçük bir canlı doğurandır. Yüzgeç didikleme eğilimi nedeniyle sakin topluluklarda dikkat ister.','[["Yetişkin boy", "6 cm"], ["Sıcaklık", "18–28 °C"], ["pH", "6.5–8.5"], ["Min. akvaryum", "50 L"], ["Huy", "Hareketli, zaman zaman hırçın"], ["Beslenme", "Omnivor"], ["Üreme", "Canlı doğuran"], ["Özellikler", "Dayanıklı, Canlı Doğuran"]]'::jsonb,array['gambusia','gambusia affinis','sivrisinek balığı','mosquitofish']::text[],false,'published'),
('heterandria-formosa','Cüce Sivrisinek Balığı','Heterandria formosa','canli-doguranlar','fish','Orta','Barışçıl','Dünyanın en küçük canlı doğuranlarından biridir. Bitkili nano akvaryumlarda sakin mikro balıklarla tutulabilir.','[["Yetişkin boy", "3,5 cm"], ["Sıcaklık", "20–27 °C"], ["pH", "7.0–8.0"], ["Min. akvaryum", "30 L"], ["Huy", "Barışçıl"], ["Beslenme", "Mikro yemler, omnivor"], ["Üreme", "Canlı doğuran"], ["Özellikler", "Nano, Canlı Doğuran"]]'::jsonb,array['heterandria formosa','least killifish','cüce sivrisinek balığı','heterandria']::text[],true,'published'),
('limia-nigrofasciata','Limia nigrofasciata','Limia nigrofasciata','canli-doguranlar','fish','Kolay','Barışçıl, hareketli','Dikey bantları ve erkeklerde belirginleşen yüksek sırt yapısıyla dikkat çeken canlı doğurandır. Grup hâlinde aktif bir görünüm sunar.','[["Yetişkin boy", "6 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "7.0–8.5"], ["Min. akvaryum", "70 L"], ["Huy", "Barışçıl, hareketli"], ["Beslenme", "Omnivor, bitkisel katkılı"], ["Üreme", "Canlı doğuran"], ["Özellikler", "Canlı Doğuran, Sürümsü"]]'::jsonb,array['limia nigrofasciata','humpbacked limia','limia','bantlı limia']::text[],true,'published'),
('limia-tridens','Tiburon Limia','Limia tridens','canli-doguranlar','fish','Kolay','Barışçıl','Sade fakat zarif desenli, dayanıklı bir Karayip canlı doğuranıdır. Sert ve alkali suya uyum sağlar.','[["Yetişkin boy", "6 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "7.0–8.5"], ["Min. akvaryum", "70 L"], ["Huy", "Barışçıl"], ["Beslenme", "Omnivor"], ["Üreme", "Canlı doğuran"], ["Özellikler", "Canlı Doğuran, Dayanıklı"]]'::jsonb,array['limia tridens','tiburon limia','tridens','limia']::text[],true,'published'),
('limia-perugiae','Dominik Limia','Limia perugiae','canli-doguranlar','fish','Kolay','Barışçıl, hareketli','Metalik tonları ve hareketli yapısıyla dikkat çeken orta boy canlı doğurandır. Erkekler kendi aralarında gösteri davranışı sergileyebilir.','[["Yetişkin boy", "8 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "7.0–8.5"], ["Min. akvaryum", "80 L"], ["Huy", "Barışçıl, hareketli"], ["Beslenme", "Omnivor"], ["Üreme", "Canlı doğuran"], ["Özellikler", "Canlı Doğuran, Renkli"]]'::jsonb,array['dominik limia','limia perugiae','perugiae limia','dominican limia','limia']::text[],true,'published'),
('xiphophorus-variatus','Kılıçsız Plati','Xiphophorus variatus','canli-doguranlar','fish','Kolay','Barışçıl','Değişken renkleri ve dayanıklılığıyla bilinen plati akrabasıdır. Serin sayılabilecek tropikal sıcaklıklara da uyum gösterebilir.','[["Yetişkin boy", "7 cm"], ["Sıcaklık", "20–27 °C"], ["pH", "7.0–8.3"], ["Min. akvaryum", "60 L"], ["Huy", "Barışçıl"], ["Beslenme", "Omnivor, bitkisel katkılı"], ["Üreme", "Canlı doğuran"], ["Özellikler", "Dayanıklı, Renkli"]]'::jsonb,array['xiphophorus variatus','variatus platy','variable platy','kılıçsız plati']::text[],false,'published'),
('xiphophorus-montezumae','Montezuma Kılıçkuyruk','Xiphophorus montezumae','canli-doguranlar','fish','Orta','Barışçıl, aktif','Erkeklerin gövdeden daha uzun olabilen etkileyici kılıcıyla tanınır. Geniş yüzme alanı ve temiz su ister.','[["Yetişkin boy", "8 cm"], ["Sıcaklık", "20–26 °C"], ["pH", "7.0–8.2"], ["Min. akvaryum", "100 L"], ["Huy", "Barışçıl, aktif"], ["Beslenme", "Omnivor"], ["Üreme", "Canlı doğuran"], ["Özellikler", "Kılıçkuyruk, Nadir Tür"]]'::jsonb,array['montezuma kılıçkuyruk','xiphophorus montezumae','montezuma swordtail','montezumae','uzun kılıçkuyruk']::text[],true,'published'),
('xiphophorus-nezahualcoyotl','Nezahualcoyotl Kılıçkuyruk','Xiphophorus nezahualcoyotl','canli-doguranlar','fish','Orta','Barışçıl, aktif','Doğal form kılıçkuyruk meraklılarının ilgi gösterdiği Meksika kökenli bir türdür. Erkeklerde uzun alt kuyruk uzantısı gelişir.','[["Yetişkin boy", "7 cm"], ["Sıcaklık", "20–26 °C"], ["pH", "7.0–8.2"], ["Min. akvaryum", "90 L"], ["Huy", "Barışçıl, aktif"], ["Beslenme", "Omnivor"], ["Üreme", "Canlı doğuran"], ["Özellikler", "Kılıçkuyruk, Nadir Tür"]]'::jsonb,array['nezahualcoyotl kılıçkuyruk','xiphophorus nezahualcoyotl','nezahualcoyotl swordtail','nezzy swordtail','xiphophorus']::text[],true,'published'),
('xiphophorus-pygmaeus','Pygmy Kılıçkuyruk','Xiphophorus pygmaeus','canli-doguranlar','fish','Orta','Barışçıl','Küçük boylu doğal bir Xiphophorus türüdür. Klasik kılıçkuyruklara göre daha kompakt tanklarda bakılabilir.','[["Yetişkin boy", "4 cm"], ["Sıcaklık", "22–27 °C"], ["pH", "7.0–8.2"], ["Min. akvaryum", "50 L"], ["Huy", "Barışçıl"], ["Beslenme", "Omnivor"], ["Üreme", "Canlı doğuran"], ["Özellikler", "Nano, Kılıçkuyruk"]]'::jsonb,array['pygmy kılıçkuyruk','xiphophorus pygmaeus','pygmy swordtail','cüce kılıçkuyruk','pygmaeus']::text[],true,'published'),
('xiphophorus-cortezi','Cortez Kılıçkuyruk','Xiphophorus cortezi','canli-doguranlar','fish','Orta','Barışçıl','Doğal desenli, zarif bir Meksika kılıçkuyruğudur. Saf tür olarak korunması için diğer Xiphophorus türleriyle melezlenmemelidir.','[["Yetişkin boy", "6 cm"], ["Sıcaklık", "20–27 °C"], ["pH", "7.0–8.2"], ["Min. akvaryum", "70 L"], ["Huy", "Barışçıl"], ["Beslenme", "Omnivor"], ["Üreme", "Canlı doğuran"], ["Özellikler", "Kılıçkuyruk, Doğal Form"]]'::jsonb,array['cortez kılıçkuyruk','xiphophorus cortezi','cortez swordtail','cortezi','doğal kılıçkuyruk']::text[],true,'published'),
('belonesox-belizanus','Belonesox','Belonesox belizanus','canli-doguranlar','fish','Zor','Avcı','Uzun çeneli, belirgin biçimde yırtıcı bir canlı doğurandır. Küçük balıkları avladığından klasik lepistes-plati topluluklarına uygun değildir.','[["Yetişkin boy", "20 cm"], ["Sıcaklık", "25–30 °C"], ["pH", "7.0–8.5"], ["Min. akvaryum", "200 L"], ["Huy", "Avcı"], ["Beslenme", "Etçil, canlı/karnivor yemler"], ["Üreme", "Canlı doğuran"], ["Özellikler", "Avcı, Canlı Doğuran"]]'::jsonb,array['belonesox belizanus','pike livebearer','belonesox','turna canlı doğuran']::text[],true,'published'),
('anableps-anableps','Dört Gözlü Balık','Anableps anableps','canli-doguranlar','fish','Zor','Sosyal, aktif','Göz yapısı suyun hem üstünü hem altını görmeye uyarlanmış sıra dışı bir canlı doğurandır. Geniş yüzey alanı ve acı suya yaklaşan mineral zengin koşullar ister.','[["Yetişkin boy", "30 cm"], ["Sıcaklık", "24–30 °C"], ["pH", "7.5–8.5"], ["Min. akvaryum", "400 L"], ["Huy", "Sosyal, aktif"], ["Beslenme", "Omnivor"], ["Üreme", "Canlı doğuran"], ["Özellikler", "Yüzey Balığı, Özel Tür"]]'::jsonb,array['anableps anableps','four eyed fish','dört gözlü balık','anableps']::text[],true,'published'),
('jenynsia-multidentata','Jenynsia','Jenynsia multidentata','canli-doguranlar','fish','Orta','Aktif, zaman zaman hırçın','Güney Amerika kökenli dayanıklı bir canlı doğurandır. Aktif yapısı ve farklı üreme biyolojisiyle koleksiyoncular için ilgi çekicidir.','[["Yetişkin boy", "9 cm"], ["Sıcaklık", "18–28 °C"], ["pH", "7.0–8.5"], ["Min. akvaryum", "100 L"], ["Huy", "Aktif, zaman zaman hırçın"], ["Beslenme", "Omnivor"], ["Üreme", "Canlı doğuran"], ["Özellikler", "Canlı Doğuran, Nadir Tür"]]'::jsonb,array['jenynsia multidentata','jenynsia','one sided livebearer','multidentata']::text[],true,'published'),
('skiffia-francesae','Skiffia francesae','Skiffia francesae','canli-doguranlar','fish','Zor','Barışçıl–yarı agresif','Goodeid grubunun nadir ve koruma değeri yüksek canlı doğuranlarındandır. Akvaryum popülasyonlarının saf tutulması önemlidir.','[["Yetişkin boy", "6 cm"], ["Sıcaklık", "20–26 °C"], ["pH", "7.0–8.2"], ["Min. akvaryum", "80 L"], ["Huy", "Barışçıl–yarı agresif"], ["Beslenme", "Omnivor, bitkisel katkılı"], ["Üreme", "Canlı doğuran"], ["Özellikler", "Goodeid, Nadir Tür"]]'::jsonb,array['skiffia francesae','golden skiffia','skiffia','goodeid']::text[],true,'published'),
('xenotoca-eiseni','Redtail Splitfin','Xenotoca eiseni','canli-doguranlar','fish','Orta','Yarı agresif','Turuncu-kırmızı kuyruk bölgesiyle dikkat çeken güçlü yapılı bir Goodeid''dir. Yüzgeç didikleme görülebileceğinden tür tankı iyi seçenektir.','[["Yetişkin boy", "7 cm"], ["Sıcaklık", "18–26 °C"], ["pH", "7.0–8.2"], ["Min. akvaryum", "80 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Omnivor, bitkisel katkılı"], ["Üreme", "Canlı doğuran"], ["Özellikler", "Goodeid, Renkli"]]'::jsonb,array['xenotoca eiseni','redtail splitfin','red tail goodeid','eiseni']::text[],true,'published'),
('ameca-splendens','Ameca Splendens','Ameca splendens','canli-doguranlar','fish','Orta','Yarı agresif, aktif','Metalik gövdesi ve erkeklerde sarı-siyah kuyruk deseniyle dikkat çeken Goodeid''dir. Aktif ve güçlü bir canlı doğurandır.','[["Yetişkin boy", "10 cm"], ["Sıcaklık", "20–28 °C"], ["pH", "7.0–8.5"], ["Min. akvaryum", "120 L"], ["Huy", "Yarı agresif, aktif"], ["Beslenme", "Omnivor, bitkisel ağırlıklı"], ["Üreme", "Canlı doğuran"], ["Özellikler", "Goodeid, Renkli"]]'::jsonb,array['ameca splendens','butterfly splitfin','ameca','goodeid']::text[],true,'published'),
('ilyodon-furcidens','Ilyodon furcidens','Ilyodon furcidens','canli-doguranlar','fish','Orta','Aktif, yarı agresif','İri sayılabilecek, aktif bir Goodeid canlı doğuranıdır. Bitkisel materyal içeren beslenme ve geniş yüzme alanı faydalıdır.','[["Yetişkin boy", "12 cm"], ["Sıcaklık", "20–27 °C"], ["pH", "7.0–8.3"], ["Min. akvaryum", "150 L"], ["Huy", "Aktif, yarı agresif"], ["Beslenme", "Omnivor, bitkisel ağırlıklı"], ["Üreme", "Canlı doğuran"], ["Özellikler", "Goodeid, İri Yapılı"]]'::jsonb,array['ilyodon furcidens','goldbreast splitfin','ilyodon','goodeid']::text[],true,'published'),
('zoogoneticus-tequila','Zoogoneticus tequila','Zoogoneticus tequila','canli-doguranlar','fish','Zor','Barışçıl–yarı agresif','Koruma çalışmalarıyla tanınan küçük bir Goodeid türüdür. Saf popülasyonların korunması ve kontrollü üretimi önemlidir.','[["Yetişkin boy", "6 cm"], ["Sıcaklık", "20–26 °C"], ["pH", "7.0–8.2"], ["Min. akvaryum", "70 L"], ["Huy", "Barışçıl–yarı agresif"], ["Beslenme", "Omnivor"], ["Üreme", "Canlı doğuran"], ["Özellikler", "Goodeid, Koruma Türü"]]'::jsonb,array['zoogoneticus tequila','tequila splitfin','tequila fish','goodeid']::text[],true,'published'),
('girardinus-metallicus','Girardinus metallicus','Girardinus metallicus','canli-doguranlar','fish','Kolay','Barışçıl','Metalik parlaklığı ve erkeklerdeki siyah desenleriyle dikkat çeken küçük canlı doğurandır. Bitkili akvaryumlarda grup hâlinde iyi görünür.','[["Yetişkin boy", "5 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "7.0–8.2"], ["Min. akvaryum", "50 L"], ["Huy", "Barışçıl"], ["Beslenme", "Omnivor"], ["Üreme", "Canlı doğuran"], ["Özellikler", "Nano, Renkli"]]'::jsonb,array['girardinus metallicus','metallic livebearer','girardinus','metalik canlı doğuran']::text[],true,'published'),
('girardinus-falcatus','Girardinus falcatus','Girardinus falcatus','canli-doguranlar','fish','Kolay','Barışçıl','Küba kökenli küçük ve hareketli bir canlı doğurandır. Sık bitkili tanklarda yavruların hayatta kalma şansı artar.','[["Yetişkin boy", "5 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "7.0–8.2"], ["Min. akvaryum", "50 L"], ["Huy", "Barışçıl"], ["Beslenme", "Omnivor"], ["Üreme", "Canlı doğuran"], ["Özellikler", "Nano, Canlı Doğuran"]]'::jsonb,array['girardinus falcatus','goldbelly topminnow','girardinus','falcatus']::text[],true,'published'),
('micropoecilia-picta','Micropoecilia picta','Micropoecilia picta','canli-doguranlar','fish','Orta','Barışçıl','Lepistese yakın akraba, küçük ve renkli bir canlı doğurandır. Doğal ve seçilimli renk formları bulunabilir.','[["Yetişkin boy", "4 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "7.0–8.2"], ["Min. akvaryum", "40 L"], ["Huy", "Barışçıl"], ["Beslenme", "Omnivor"], ["Üreme", "Canlı doğuran"], ["Özellikler", "Nano, Renkli"]]'::jsonb,array['micropoecilia picta','poecilia picta','swamp guppy','picta guppy']::text[],true,'published'),
('poecilia-salvatoris','Liberty Molly','Poecilia salvatoris','canli-doguranlar','fish','Orta','Aktif','Orta Amerika kökenli doğal bir Poecilia türüdür. Erkeklerin yüzgeçlerindeki kırmızı-siyah tonlar dikkat çekicidir.','[["Yetişkin boy", "8 cm"], ["Sıcaklık", "23–28 °C"], ["pH", "7.0–8.5"], ["Min. akvaryum", "80 L"], ["Huy", "Aktif"], ["Beslenme", "Omnivor, bitkisel katkılı"], ["Üreme", "Canlı doğuran"], ["Özellikler", "Renkli, Canlı Doğuran"]]'::jsonb,array['poecilia salvatoris','liberty molly','salvatoris','el salvador molly']::text[],true,'published'),
('poecilia-latipinna','Sailfin Molly','Poecilia latipinna','canli-doguranlar','fish','Kolay','Barışçıl, aktif','Erkeklerin büyük yelken biçimli sırt yüzgeciyle tanınır. Mineralce zengin, sert sularda iyi gelişir.','[["Yetişkin boy", "12 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "7.2–8.5"], ["Min. akvaryum", "100 L"], ["Huy", "Barışçıl, aktif"], ["Beslenme", "Omnivor, bitkisel ağırlıklı"], ["Üreme", "Canlı doğuran"], ["Özellikler", "Yelken Yüzgeçli, Canlı Doğuran"]]'::jsonb,array['poecilia latipinna','sailfin molly','yelken moli','latipinna']::text[],false,'published'),
('poecilia-velifera','Giant Sailfin Molly','Poecilia velifera','canli-doguranlar','fish','Orta','Barışçıl, aktif','Çok büyük sırt yüzgeci ve iri yapısıyla gösterişli bir moli türüdür. Sert, alkali ve mineralce zengin suyu tercih eder.','[["Yetişkin boy", "15 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "7.2–8.5"], ["Min. akvaryum", "120 L"], ["Huy", "Barışçıl, aktif"], ["Beslenme", "Omnivor, bitkisel ağırlıklı"], ["Üreme", "Canlı doğuran"], ["Özellikler", "Yelken Yüzgeçli, İri Molly"]]'::jsonb,array['poecilia velifera','giant sailfin molly','velifera','yucatan molly']::text[],false,'published'),
('poecilia-chica','Dwarf Molly','Poecilia chica','canli-doguranlar','fish','Orta','Barışçıl','Küçük boylu doğal bir moli akrabasıdır. Bitkili ve mineralce zengin akvaryumlarda küçük gruplar hâlinde tutulabilir.','[["Yetişkin boy", "5 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "7.0–8.3"], ["Min. akvaryum", "50 L"], ["Huy", "Barışçıl"], ["Beslenme", "Omnivor, bitkisel katkılı"], ["Üreme", "Canlı doğuran"], ["Özellikler", "Nano, Nadir Tür"]]'::jsonb,array['poecilia chica','dwarf molly','chica molly','poecilia']::text[],true,'published'),
('priapella-intermedia','Priapella intermedia','Priapella intermedia','canli-doguranlar','fish','Orta','Barışçıl, sosyal','Şeffaf-sarımsı gövdesi ve mavi gözleriyle zarif bir canlı doğurandır. Temiz, oksijenli su ve grup hâlinde bakım uygundur.','[["Yetişkin boy", "6 cm"], ["Sıcaklık", "22–27 °C"], ["pH", "7.0–8.0"], ["Min. akvaryum", "70 L"], ["Huy", "Barışçıl, sosyal"], ["Beslenme", "Omnivor, küçük canlı yemler"], ["Üreme", "Canlı doğuran"], ["Özellikler", "Mavi Gözlü, Sosyal"]]'::jsonb,array['priapella intermedia','blue eyed livebearer','priapella','intermedia']::text[],true,'published'),
('alfaro-cultratus','Alfaro cultratus','Alfaro cultratus','canli-doguranlar','fish','Orta','Barışçıl, aktif','İnce ve bıçak benzeri karın hattıyla ayırt edilen hızlı bir canlı doğurandır. Akıntılı, temiz su ve yüzme alanı ister.','[["Yetişkin boy", "8 cm"], ["Sıcaklık", "23–28 °C"], ["pH", "6.5–8.0"], ["Min. akvaryum", "100 L"], ["Huy", "Barışçıl, aktif"], ["Beslenme", "Omnivor, böcekçil eğilimli"], ["Üreme", "Canlı doğuran"], ["Özellikler", "Aktif, Nadir Tür"]]'::jsonb,array['alfaro cultratus','knife livebearer','alfaro','cultratus']::text[],true,'published'),
('dermogenys-pusilla','Dermogenys pusilla','Dermogenys pusilla','canli-doguranlar','fish','Orta','Yüzeyci, erkekler rekabetçi','Yüzeyde yaşayan yarım gagalı canlı doğurandır. Erkekler kendi aralarında rekabet edebildiğinden uzun yüzey alanı önemlidir.','[["Yetişkin boy", "7 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "7.0–8.0"], ["Min. akvaryum", "80 L"], ["Huy", "Yüzeyci, erkekler rekabetçi"], ["Beslenme", "Omnivor, böcekçil"], ["Üreme", "Canlı doğuran"], ["Özellikler", "Yüzey Balığı, Yarım Gagalı"]]'::jsonb,array['dermogenys pusilla','dermogenys pusillus','wrestling halfbeak','halfbeak','yarım gagalı']::text[],false,'published'),
('nomorhamphus-liemi','Nomorhamphus liemi','Nomorhamphus liemi','canli-doguranlar','fish','Orta','Yüzeyci, yarı agresif','Sulawesi kökenli, kırmızı yüzgeçli gösterişli bir yarım gagalıdır. Yüzey alanı geniş, kapaklı akvaryum ister.','[["Yetişkin boy", "9 cm"], ["Sıcaklık", "23–27 °C"], ["pH", "7.0–8.0"], ["Min. akvaryum", "100 L"], ["Huy", "Yüzeyci, yarı agresif"], ["Beslenme", "Omnivor, böcekçil"], ["Üreme", "Canlı doğuran"], ["Özellikler", "Yarım Gagalı, Renkli"]]'::jsonb,array['nomorhamphus liemi','celebes halfbeak','liemi','red fin halfbeak']::text[],true,'published'),
('nomorhamphus-ebrardtii','Nomorhamphus ebrardtii','Nomorhamphus ebrardtii','canli-doguranlar','fish','Orta','Yüzeyci','Sulawesi''nin akarsu sistemlerinden gelen zarif bir yarım gagalıdır. Sıçrayabildiği için kapak ve sakin yüzey alanı önemlidir.','[["Yetişkin boy", "8 cm"], ["Sıcaklık", "23–27 °C"], ["pH", "7.0–8.0"], ["Min. akvaryum", "90 L"], ["Huy", "Yüzeyci"], ["Beslenme", "Omnivor, böcekçil"], ["Üreme", "Canlı doğuran"], ["Özellikler", "Yarım Gagalı, Nadir Tür"]]'::jsonb,array['nomorhamphus ebrardtii','ebrardtii halfbeak','nomorhamphus','halfbeak']::text[],true,'published')
insert into public.species (slug,name,latin,category_id,kind,difficulty,temperament,description,facts,keywords,is_rare,status) values
('trichopodus-leerii','İnci Gurami','Trichopodus leerii','labirentliler','fish','Kolay','Barışçıl','İnci desenli gövdesi ve sakin karakteriyle klasik labirent balıklarındandır. Bitkili, düşük akıntılı akvaryumlarda en iyi görünümünü sergiler.','[["Yetişkin boy", "12 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "5.5–8.0"], ["Min. akvaryum", "100 L"], ["Huy", "Barışçıl"], ["Beslenme", "Omnivor"], ["Üreme", "Köpük yuva"], ["Özellikler", "Barışçıl, Renkli"]]'::jsonb,array['inci gurami','trichopodus leerii','pearl gourami','leerii']::text[],false,'published'),
('trichogaster-chuna','Bal Gurami','Trichogaster chuna','labirentliler','fish','Kolay','Barışçıl','Küçük, sakin ve renkli bir guramidir. Yoğun bitkili, sakin topluluk akvaryumlarına uygundur.','[["Yetişkin boy", "5 cm"], ["Sıcaklık", "23–28 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "50 L"], ["Huy", "Barışçıl"], ["Beslenme", "Omnivor"], ["Üreme", "Köpük yuva"], ["Özellikler", "Nano, Barışçıl"]]'::jsonb,array['bal gurami','trichogaster chuna','honey gourami','chuna']::text[],false,'published'),
('trichogaster-labiosa','Kalın Dudaklı Gurami','Trichogaster labiosa','labirentliler','fish','Kolay','Barışçıl','Bal guramiye göre daha iri, sakin karakterli bir türdür. Bitkili tanklarda çift veya küçük grup düzeninde bakılabilir.','[["Yetişkin boy", "9 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "80 L"], ["Huy", "Barışçıl"], ["Beslenme", "Omnivor"], ["Üreme", "Köpük yuva"], ["Özellikler", "Barışçıl, Orta Boy"]]'::jsonb,array['kalın dudaklı gurami','trichogaster labiosa','thick lipped gourami','labiosa']::text[],false,'published'),
('trichogaster-fasciata','Bantlı Gurami','Trichogaster fasciata','labirentliler','fish','Orta','Barışçıl–yarı agresif','Dikey bantları ve turuncu-mavi renkleriyle dikkat çeken orta boy guramidir. Sakin ve bitkili tanklarda iyi gelişir.','[["Yetişkin boy", "12 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "100 L"], ["Huy", "Barışçıl–yarı agresif"], ["Beslenme", "Omnivor"], ["Üreme", "Köpük yuva"], ["Özellikler", "Renkli, Bitkili Tank"]]'::jsonb,array['bantlı gurami','trichogaster fasciata','banded gourami','fasciata']::text[],true,'published'),
('trichopodus-microlepis','Ayışığı Gurami','Trichopodus microlepis','labirentliler','fish','Kolay','Barışçıl','Gümüş renkli, iri ve zarif bir guramidir. Geniş yüzme alanı ile bitkili kenar bölgelerinin birlikte bulunması uygundur.','[["Yetişkin boy", "15 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "150 L"], ["Huy", "Barışçıl"], ["Beslenme", "Omnivor"], ["Üreme", "Köpük yuva"], ["Özellikler", "İri Gurami, Barışçıl"]]'::jsonb,array['ayışığı gurami','trichopodus microlepis','moonlight gourami','microlepis']::text[],false,'published'),
('osphronemus-goramy','Dev Gurami','Osphronemus goramy','labirentliler','fish','Zor','Yarı agresif, iri','Çok büyük boyutlara ulaşan, uzun ömürlü bir labirent balığıdır. Ev akvaryumları için ancak çok büyük hacimlerde uygundur.','[["Yetişkin boy", "70 cm"], ["Sıcaklık", "24–30 °C"], ["pH", "6.5–8.0"], ["Min. akvaryum", "1000 L"], ["Huy", "Yarı agresif, iri"], ["Beslenme", "Omnivor, bitkisel ağırlıklı"], ["Üreme", "Köpük/bitkisel yuva"], ["Özellikler", "Dev Balık, Uzun Ömürlü"]]'::jsonb,array['dev gurami','osphronemus goramy','giant gourami','goramy']::text[],false,'published'),
('sphaerichthys-osphromenoides','Çikolata Gurami','Sphaerichthys osphromenoides','labirentliler','fish','Zor','Barışçıl, hassas','Koyu çikolata rengi ve krem bantlarıyla sıra dışı bir guramidir. Yumuşak, asidik ve çok temiz su istediğinden deneyim gerektirir.','[["Yetişkin boy", "6 cm"], ["Sıcaklık", "25–30 °C"], ["pH", "4.0–6.5"], ["Min. akvaryum", "60 L"], ["Huy", "Barışçıl, hassas"], ["Beslenme", "Omnivor, küçük canlı/dondurulmuş yem"], ["Üreme", "Ağızda kuluçka"], ["Özellikler", "Hassas, Siyah Su"]]'::jsonb,array['çikolata gurami','sphaerichthys osphromenoides','chocolate gourami','osphromenoides']::text[],true,'published'),
('sphaerichthys-vaillanti','Vaillant Çikolata Gurami','Sphaerichthys vaillanti','labirentliler','fish','Zor','Barışçıl, hassas','Dişilerde belirgin kırmızı-yeşil desenler görülen nadir bir siyah su guramisidir. Çok yumuşak ve asidik su koşulları ister.','[["Yetişkin boy", "6 cm"], ["Sıcaklık", "25–30 °C"], ["pH", "4.0–6.5"], ["Min. akvaryum", "60 L"], ["Huy", "Barışçıl, hassas"], ["Beslenme", "Küçük canlı/dondurulmuş yem"], ["Üreme", "Ağızda kuluçka"], ["Özellikler", "Nadir Tür, Siyah Su"]]'::jsonb,array['vaillant çikolata gurami','sphaerichthys vaillanti','vaillant chocolate gourami','vaillanti','samurai gourami']::text[],true,'published'),
('sphaerichthys-selatanensis','Samuray Gurami','Sphaerichthys selatanensis','labirentliler','fish','Zor','Barışçıl, hassas','Çikolata gurami grubunun narin bir üyesidir. Yaprak çürüntülü, düşük iletkenlikli ve sakin akvaryumları tercih eder.','[["Yetişkin boy", "5 cm"], ["Sıcaklık", "25–30 °C"], ["pH", "4.0–6.5"], ["Min. akvaryum", "60 L"], ["Huy", "Barışçıl, hassas"], ["Beslenme", "Küçük canlı/dondurulmuş yem"], ["Üreme", "Ağızda kuluçka"], ["Özellikler", "Siyah Su, Nadir Tür"]]'::jsonb,array['samuray gurami','sphaerichthys selatanensis','selatan chocolate gourami','selatanensis','chocolate gourami']::text[],true,'published'),
('parosphromenus-deissneri','Licorice Gurami','Parosphromenus deissneri','labirentliler','fish','Zor','Barışçıl, hassas','Turba bataklıklarının çok yumuşak ve asidik sularına uyumlu küçük bir labirent balığıdır. Gerçek P. deissneri hobi piyasasında son derece nadirdir.','[["Yetişkin boy", "4 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "3.0–6.0"], ["Min. akvaryum", "30 L"], ["Huy", "Barışçıl, hassas"], ["Beslenme", "Mikro canlı yemler"], ["Üreme", "Mağara/köpük yuva"], ["Özellikler", "Nano, Siyah Su"]]'::jsonb,array['licorice gurami','parosphromenus deissneri','licorice gourami','deissneri','parosphromenus']::text[],true,'published'),
('parosphromenus-linkei','Parosphromenus linkei','Parosphromenus linkei','labirentliler','fish','Zor','Barışçıl, hassas','Koyu gövde üzerindeki metalik mavi-yeşil benekleriyle dikkat çeken küçük siyah su türüdür. Çok düşük mineral ve asidik su ister.','[["Yetişkin boy", "4 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "3.0–6.0"], ["Min. akvaryum", "30 L"], ["Huy", "Barışçıl, hassas"], ["Beslenme", "Mikro canlı yemler"], ["Üreme", "Mağara/köpük yuva"], ["Özellikler", "Nano, Nadir Tür"]]'::jsonb,array['parosphromenus linkei','linkei','licorice gourami','parosphromenus']::text[],true,'published'),
('parosphromenus-nagyi','Parosphromenus nagyi','Parosphromenus nagyi','labirentliler','fish','Zor','Barışçıl, hassas','İnce yapılı, renkli yüzgeçlere sahip bir turba bataklığı labirent balığıdır. Tür tankı ve canlı mikro yemler tercih edilir.','[["Yetişkin boy", "4 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "3.5–6.0"], ["Min. akvaryum", "30 L"], ["Huy", "Barışçıl, hassas"], ["Beslenme", "Mikro canlı yemler"], ["Üreme", "Mağara/köpük yuva"], ["Özellikler", "Nano, Siyah Su"]]'::jsonb,array['parosphromenus nagyi','nagyi','licorice gourami','parosphromenus']::text[],true,'published'),
('trichopsis-pumila','Cüce Köpük Gurami','Trichopsis pumila','labirentliler','fish','Kolay','Barışçıl','Küçük boylu, ses çıkarabilen ve ışıldayan mavi-yeşil beneklere sahip bir labirent balığıdır. Nano, bitkili akvaryumlara uygundur.','[["Yetişkin boy", "4 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "5.0–7.5"], ["Min. akvaryum", "30 L"], ["Huy", "Barışçıl"], ["Beslenme", "Omnivor, mikro yemler"], ["Üreme", "Köpük yuva"], ["Özellikler", "Nano, Barışçıl"]]'::jsonb,array['trichopsis pumila','sparkling gourami','cüce köpük gurami','pumila']::text[],false,'published'),
('trichopsis-vittata','Hırıltılı Gurami','Trichopsis vittata','labirentliler','fish','Kolay','Barışçıl–yarı agresif','Üreme ve rekabet sırasında duyulabilir sesler çıkarabilen ilginç bir guramidir. Bitkili ve sakin akvaryumlarda grup hâlinde tutulabilir.','[["Yetişkin boy", "7 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "5.0–8.0"], ["Min. akvaryum", "60 L"], ["Huy", "Barışçıl–yarı agresif"], ["Beslenme", "Omnivor"], ["Üreme", "Köpük yuva"], ["Özellikler", "Ses Çıkaran, Bitkili Tank"]]'::jsonb,array['trichopsis vittata','croaking gourami','hırıltılı gurami','vittata']::text[],true,'published'),
('betta-imbellis','Betta imbellis','Betta imbellis','labirentliler','fish','Orta','Yarı agresif','Betta splendens''e benzeyen fakat genellikle daha sakin doğal bir Betta türüdür. Erkeklerde metalik mavi-yeşil ve kırmızı tonlar görülür.','[["Yetişkin boy", "6 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "5.0–7.5"], ["Min. akvaryum", "40 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Omnivor, böcekçil"], ["Üreme", "Köpük yuva"], ["Özellikler", "Doğal Betta, Renkli"]]'::jsonb,array['betta imbellis','peaceful betta','crescent betta','imbellis']::text[],true,'published'),
('betta-smaragdina','Betta smaragdina','Betta smaragdina','labirentliler','fish','Orta','Yarı agresif','Metalik zümrüt pullarıyla dikkat çeken doğal bir Betta türüdür. Sakin, bitkili ve düşük akıntılı akvaryumlarda iyi gelişir.','[["Yetişkin boy", "7 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "5.5–8.0"], ["Min. akvaryum", "40 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Omnivor, böcekçil"], ["Üreme", "Köpük yuva"], ["Özellikler", "Doğal Betta, Renkli"]]'::jsonb,array['betta smaragdina','emerald betta','smaragdina','zümrüt betta']::text[],true,'published'),
('betta-mahachaiensis','Betta mahachaiensis','Betta mahachaiensis','labirentliler','fish','Orta','Yarı agresif','Tayland''ın kıyıya yakın habitatlarından gelen metalik yeşil desenli doğal Betta türüdür. Saf tür olarak korunması önemlidir.','[["Yetişkin boy", "6 cm"], ["Sıcaklık", "24–29 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "40 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Omnivor, böcekçil"], ["Üreme", "Köpük yuva"], ["Özellikler", "Doğal Betta, Nadir Tür"]]'::jsonb,array['betta mahachaiensis','mahachai betta','mahachaiensis','green betta']::text[],true,'published'),
('betta-albimarginata','Betta albimarginata','Betta albimarginata','labirentliler','fish','Zor','Barışçıl–yarı agresif','Beyaz kenarlı yüzgeçleri ve kırmızı tonlarıyla tanınan küçük ağızda kuluçkacı Betta''dır. Sakin ve gölgeli tür akvaryumlarında başarılı olur.','[["Yetişkin boy", "5 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "4.0–6.5"], ["Min. akvaryum", "40 L"], ["Huy", "Barışçıl–yarı agresif"], ["Beslenme", "Küçük canlı/dondurulmuş yem"], ["Üreme", "Ağızda kuluçka"], ["Özellikler", "Ağızda Kuluçka, Nadir Tür"]]'::jsonb,array['betta albimarginata','white seam betta','albimarginata','mouthbrooding betta']::text[],true,'published'),
('betta-channoides','Betta channoides','Betta channoides','labirentliler','fish','Zor','Barışçıl–yarı agresif','Turuncu-kırmızı erkekleri ve ağızda kuluçka davranışıyla dikkat çeken küçük doğal Betta''dır. Yumuşak ve hafif asidik suyu tercih eder.','[["Yetişkin boy", "5 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "4.0–6.5"], ["Min. akvaryum", "40 L"], ["Huy", "Barışçıl–yarı agresif"], ["Beslenme", "Küçük canlı/dondurulmuş yem"], ["Üreme", "Ağızda kuluçka"], ["Özellikler", "Ağızda Kuluçka, Renkli"]]'::jsonb,array['betta channoides','snakehead betta','channoides','mouthbrooding betta']::text[],true,'published'),
('betta-macrostoma','Betta macrostoma','Betta macrostoma','labirentliler','fish','Zor','Yarı agresif','Brunei Beauty adıyla bilinen, büyük ağızlı ve gösterişli bir ağızda kuluçkacı Betta''dır. Hassas su kalitesi ve güvenli kapak gerektirir.','[["Yetişkin boy", "10 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "4.5–6.5"], ["Min. akvaryum", "80 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Etçil ağırlıklı"], ["Üreme", "Ağızda kuluçka"], ["Özellikler", "Nadir Tür, Ağızda Kuluçka"]]'::jsonb,array['betta macrostoma','brunei beauty','macrostoma','mouthbrooding betta']::text[],true,'published'),
('betta-unimaculata','Betta unimaculata','Betta unimaculata','labirentliler','fish','Orta','Yarı agresif','İri doğal Betta grubundandır ve erkek ağızda kuluçka yapar. Güçlü sıçrama yeteneği nedeniyle akvaryum mutlaka kapalı olmalıdır.','[["Yetişkin boy", "12 cm"], ["Sıcaklık", "23–28 °C"], ["pH", "5.0–7.5"], ["Min. akvaryum", "100 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Etçil ağırlıklı omnivor"], ["Üreme", "Ağızda kuluçka"], ["Özellikler", "İri Betta, Ağızda Kuluçka"]]'::jsonb,array['betta unimaculata','unimaculata','one spot betta','mouthbrooding betta']::text[],true,'published'),
('betta-pugnax','Betta pugnax','Betta pugnax','labirentliler','fish','Orta','Yarı agresif','Orta boylu ve erkek ağızda kuluçkacı doğal Betta türüdür. Yaprak çürüntülü, gölgeli akvaryumlarda doğal davranışlarını sergiler.','[["Yetişkin boy", "7 cm"], ["Sıcaklık", "23–28 °C"], ["pH", "5.0–7.5"], ["Min. akvaryum", "60 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Omnivor, böcekçil"], ["Üreme", "Ağızda kuluçka"], ["Özellikler", "Doğal Betta, Ağızda Kuluçka"]]'::jsonb,array['betta pugnax','penang betta','pugnax','mouthbrooding betta']::text[],true,'published'),
('betta-simplex','Betta simplex','Betta simplex','labirentliler','fish','Zor','Yarı agresif','Tayland''a özgü ağızda kuluçkacı doğal Betta türüdür. Diğer birçok yabani Betta''ya göre daha mineralce zengin suyu tolere eder.','[["Yetişkin boy", "8 cm"], ["Sıcaklık", "23–28 °C"], ["pH", "6.5–8.0"], ["Min. akvaryum", "60 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Omnivor, böcekçil"], ["Üreme", "Ağızda kuluçka"], ["Özellikler", "Endemik, Ağızda Kuluçka"]]'::jsonb,array['betta simplex','krabi mouthbrooding betta','simplex','betta']::text[],true,'published'),
('pseudosphromenus-dayi','Cüce Cennet Balığı','Pseudosphromenus dayi','labirentliler','fish','Orta','Yarı agresif','Koyu gövde ve mavi-kırmızı yüzgeçleriyle küçük, zarif bir labirent balığıdır. Bitkili ve sakin tanklarda çift olarak bakılabilir.','[["Yetişkin boy", "7 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "50 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Omnivor"], ["Üreme", "Köpük yuva"], ["Özellikler", "Küçük Yapılı, Renkli"]]'::jsonb,array['pseudosphromenus dayi','dayi','dwarf paradise fish','cüce cennet balığı']::text[],true,'published'),
('pseudosphromenus-cupanus','Siyah Cennet Balığı','Pseudosphromenus cupanus','labirentliler','fish','Orta','Yarı agresif','Koyu tonlu, dayanıklı fakat hobi piyasasında seyrek görülen küçük bir labirent balığıdır. Sakin bitkili tankları tercih eder.','[["Yetişkin boy", "7 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "50 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Omnivor"], ["Üreme", "Köpük yuva"], ["Özellikler", "Nadir Tür, Bitkili Tank"]]'::jsonb,array['siyah cennet balığı','pseudosphromenus cupanus','spiketail paradise fish','cupanus','black paradise fish']::text[],true,'published'),
('macropodus-ocellatus','Macropodus ocellatus','Macropodus ocellatus','labirentliler','fish','Orta','Yarı agresif','Soğuğa dayanıklılığıyla öne çıkan cennet balığı akrabasıdır. Mevsimsel sıcaklık değişimlerini birçok tropikal türden daha iyi tolere eder.','[["Yetişkin boy", "12 cm"], ["Sıcaklık", "10–25 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "100 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Omnivor"], ["Üreme", "Köpük yuva"], ["Özellikler", "Serin Su, Nadir Tür"]]'::jsonb,array['macropodus ocellatus','roundtail paradise fish','ocellatus paradise fish','macropodus']::text[],true,'published'),
('macropodus-spechti','Macropodus spechti','Macropodus spechti','labirentliler','fish','Orta','Yarı agresif','Koyu siyaha yakın gövdesiyle dikkat çeken Vietnam kökenli cennet balığıdır. Dayanıklı olmakla birlikte erkekler bölgeci olabilir.','[["Yetişkin boy", "10 cm"], ["Sıcaklık", "18–27 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "80 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Omnivor"], ["Üreme", "Köpük yuva"], ["Özellikler", "Koyu Renkli, Dayanıklı"]]'::jsonb,array['macropodus spechti','black paradise fish','spechti','vietnam paradise fish']::text[],true,'published'),
('luciocephalus-pulcher','Luciocephalus pulcher','Luciocephalus pulcher','labirentliler','fish','Zor','Avcı, sakin','Uzun başlı, pusu kurarak küçük balık ve omurgasız avlayan sıra dışı bir labirent balığıdır. Yumuşak, asidik su ve özel besleme ister.','[["Yetişkin boy", "20 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "4.0–6.5"], ["Min. akvaryum", "150 L"], ["Huy", "Avcı, sakin"], ["Beslenme", "Etçil"], ["Üreme", "Ağızda kuluçka"], ["Özellikler", "Avcı, Siyah Su"]]'::jsonb,array['luciocephalus pulcher','pikehead','luciocephalus','crocodile fish']::text[],true,'published'),
('ctenopoma-acutirostre','Ctenopoma acutirostre','Ctenopoma acutirostre','labirentliler','fish','Orta','Sakin avcı','Leopar desenli, Afrika kökenli pusu avcısı bir labirent balığıdır. Küçük tank arkadaşlarını avlayabilir ancak benzer boydaki balıklara karşı genellikle sakindir.','[["Yetişkin boy", "15 cm"], ["Sıcaklık", "23–28 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "150 L"], ["Huy", "Sakin avcı"], ["Beslenme", "Etçil ağırlıklı"], ["Üreme", "Yumurta saçıcı"], ["Özellikler", "Avcı, Leopar Desenli"]]'::jsonb,array['ctenopoma acutirostre','leopard bushfish','leopard ctenopoma','benekli ctenopoma']::text[],false,'published'),
('microctenopoma-ansorgii','Microctenopoma ansorgii','Microctenopoma ansorgii','labirentliler','fish','Orta','Barışçıl–yarı agresif','Turuncu-kahverengi bantlarıyla dikkat çeken küçük Afrika labirent balığıdır. Yoğun bitkili, sakin akvaryumlarda bakılabilir.','[["Yetişkin boy", "8 cm"], ["Sıcaklık", "23–28 °C"], ["pH", "5.5–7.5"], ["Min. akvaryum", "60 L"], ["Huy", "Barışçıl–yarı agresif"], ["Beslenme", "Etçil ağırlıklı omnivor"], ["Üreme", "Köpük yuva"], ["Özellikler", "Renkli, Nadir Tür"]]'::jsonb,array['microctenopoma ansorgii','ornate ctenopoma','ansorgii','african labyrinth fish']::text[],true,'published'),
('microctenopoma-fasciolatum','Microctenopoma fasciolatum','Microctenopoma fasciolatum','labirentliler','fish','Orta','Yarı agresif','Bantlı gövdesi ve sakin görünümüyle küçük Afrika labirent balıklarındandır. Bitkili, gölgeli tankları tercih eder.','[["Yetişkin boy", "9 cm"], ["Sıcaklık", "23–28 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "70 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Omnivor, etçil ağırlıklı"], ["Üreme", "Köpük yuva"], ["Özellikler", "Bantlı, Afrika Türü"]]'::jsonb,array['microctenopoma fasciolatum','banded bushfish','fasciolatum','microctenopoma']::text[],true,'published'),
('helostoma-temminckii','Öpüşen Gurami','Helostoma temminckii','labirentliler','fish','Orta','Yarı agresif, sosyal','Kalın dudakları ve ''öpüşme'' şeklindeki rekabet davranışıyla tanınır. İri büyüdüğü için yetişkinlerde geniş hacim gerekir.','[["Yetişkin boy", "25 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "300 L"], ["Huy", "Yarı agresif, sosyal"], ["Beslenme", "Omnivor, alg/bitkisel katkılı"], ["Üreme", "Yumurta saçıcı"], ["Özellikler", "İri Gurami, Öpüşme Davranışı"]]'::jsonb,array['öpüşen gurami','kissing gurami','kissing gourami','helostoma temminckii','kissing fish']::text[],false,'published')
insert into public.species (slug,name,latin,category_id,kind,difficulty,temperament,description,facts,keywords,is_rare,status) values
('puntius-titteya','Kiraz Barb','Puntius titteya','sazangiller','fish','Kolay','Barışçıl, sürü balığı','Erkekleri üreme döneminde yoğun kiraz kırmızısına dönen küçük ve barışçıl bir sazangildir. Bitkili topluluk akvaryumları için uygundur.','[["Yetişkin boy", "5 cm"], ["Sıcaklık", "23–28 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "50 L"], ["Huy", "Barışçıl, sürü balığı"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçıcı"], ["Özellikler", "Sürü Balığı, Renkli"]]'::jsonb,array['kiraz barb','puntius titteya','cherry barb','titteya']::text[],false,'published'),
('desmopuntius-pentazona','Beş Bantlı Barb','Desmopuntius pentazona','sazangiller','fish','Orta','Barışçıl, sürü balığı','Turuncu gövde üzerindeki beş koyu bantla tanınan sakin bir barb türüdür. Sürü hâlinde ve bitkili tanklarda daha rahat davranır.','[["Yetişkin boy", "5 cm"], ["Sıcaklık", "23–28 °C"], ["pH", "5.0–7.0"], ["Min. akvaryum", "60 L"], ["Huy", "Barışçıl, sürü balığı"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçıcı"], ["Özellikler", "Sürü Balığı, Çizgili"]]'::jsonb,array['desmopuntius pentazona','five banded barb','beş bantlı barb','pentazona']::text[],false,'published'),
('desmopuntius-hexazona','Altı Bantlı Barb','Desmopuntius hexazona','sazangiller','fish','Orta','Barışçıl, sürü balığı','Koyu dikey bantları ve sıcak turuncu tonlarıyla dikkat çeker. Yumuşak-asidik suya ve sakin sürü düzenine uygundur.','[["Yetişkin boy", "5 cm"], ["Sıcaklık", "23–28 °C"], ["pH", "4.5–7.0"], ["Min. akvaryum", "60 L"], ["Huy", "Barışçıl, sürü balığı"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçıcı"], ["Özellikler", "Sürü Balığı, Siyah Su"]]'::jsonb,array['altı bantlı barb','desmopuntius hexazona','six banded barb','hexazona','tiger barb relative']::text[],true,'published'),
('pethia-padamya','Odessa Barb','Pethia padamya','sazangiller','fish','Kolay','Barışçıl, aktif sürü','Erkeklerin gövdesindeki parlak kırmızı yatay şeritle tanınır. Aktif sürü balığıdır ve geniş yüzme alanını sever.','[["Yetişkin boy", "7 cm"], ["Sıcaklık", "20–26 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "80 L"], ["Huy", "Barışçıl, aktif sürü"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçıcı"], ["Özellikler", "Sürü Balığı, Renkli"]]'::jsonb,array['odessa barb','pethia padamya','padamya','kırmızı şeritli barb']::text[],false,'published'),
('pethia-conchonius','Rosy Barb','Pethia conchonius','sazangiller','fish','Kolay','Barışçıl, aktif sürü','Dayanıklı, hareketli ve serin suya toleranslı bir barb türüdür. Erkekler kırmızı-pembe tonlarıyla dikkat çeker.','[["Yetişkin boy", "10 cm"], ["Sıcaklık", "18–26 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "100 L"], ["Huy", "Barışçıl, aktif sürü"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçıcı"], ["Özellikler", "Dayanıklı, Sürü Balığı"]]'::jsonb,array['rosy barb','pethia conchonius','pembe barb','conchonius']::text[],false,'published'),
('barbodes-semifasciolatus','Altın Barb','Barbodes semifasciolatus','sazangiller','fish','Kolay','Barışçıl, sürü balığı','Altın renkli ticari formuyla tanınan dayanıklı ve aktif sazangildir. Serin-tropikal arası sıcaklıklarda rahat eder.','[["Yetişkin boy", "8 cm"], ["Sıcaklık", "18–26 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "80 L"], ["Huy", "Barışçıl, sürü balığı"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçıcı"], ["Özellikler", "Dayanıklı, Altın Renkli"]]'::jsonb,array['gold barb','barbodes semifasciolatus','chinese barb','altın barb']::text[],false,'published'),
('barbonymus-schwanenfeldii','Tinfoil Barb','Barbonymus schwanenfeldii','sazangiller','fish','Orta','Barışçıl, çok aktif','Parlak gümüş gövdesi ve kırmızı yüzgeçleriyle iri bir sürü balığıdır. Hızlı büyüdüğü için çok büyük akvaryum gerektirir.','[["Yetişkin boy", "35 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "600 L"], ["Huy", "Barışçıl, çok aktif"], ["Beslenme", "Omnivor, bitkisel ağırlıklı"], ["Üreme", "Yumurta saçıcı"], ["Özellikler", "İri Yapılı, Sürü Balığı"]]'::jsonb,array['tinfoil barb','barbonymus schwanenfeldii','silver barb','folyo barb']::text[],false,'published'),
('sahyadria-denisonii','Denison Barb','Sahyadria denisonii','sazangiller','fish','Orta','Barışçıl, aktif sürü','Kırmızı burun çizgisi ve siyah yatay bandıyla çok gösterişli bir sürü balığıdır. Oksijenli, temiz su ve uzun yüzme alanı ister.','[["Yetişkin boy", "15 cm"], ["Sıcaklık", "20–26 °C"], ["pH", "6.5–7.8"], ["Min. akvaryum", "200 L"], ["Huy", "Barışçıl, aktif sürü"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçıcı"], ["Özellikler", "Sürü Balığı, Renkli"]]'::jsonb,array['denison barb','sahyadria denisonii','roseline shark','denisonii']::text[],false,'published'),
('haludaria-fasciata','Melon Barb','Haludaria fasciata','sazangiller','fish','Orta','Barışçıl, sürü balığı','Kırmızımsı gövdesi ve koyu bantlarıyla dikkat çeken Hindistan kökenli bir barb türüdür. Grup hâlinde tutulduğunda renk ve davranış daha iyi gelişir.','[["Yetişkin boy", "7 cm"], ["Sıcaklık", "20–26 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "80 L"], ["Huy", "Barışçıl, sürü balığı"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçıcı"], ["Özellikler", "Sürü Balığı, Nadir Tür"]]'::jsonb,array['haludaria fasciata','melon barb','fasciata barb','indian barb']::text[],true,'published'),
('dawkinsia-filamentosa','Kırmızı Çizgili Torpido Barb','Dawkinsia filamentosa','sazangiller','fish','Orta','Barışçıl, aktif','Erkeklerde uzayan sırt yüzgeci ışınları ve gövde renkleriyle gösterişli bir sürü balığıdır. Uzun akvaryum ve güçlü filtrasyon ister.','[["Yetişkin boy", "15 cm"], ["Sıcaklık", "20–27 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "200 L"], ["Huy", "Barışçıl, aktif"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçıcı"], ["Özellikler", "Sürü Balığı, Uzun Yüzgeçli"]]'::jsonb,array['kırmızı çizgili torpido barb','dawkinsia filamentosa','filament barb','filamentosa','blackspot barb']::text[],true,'published'),
('dawkinsia-arulius','Arulius Barb','Dawkinsia arulius','sazangiller','fish','Orta','Barışçıl, aktif sürü','Yetişkin erkeklerde uzayan sırt yüzgeci ve koyu gövde lekeleriyle dikkat çeker. Aktif sürü yapısı nedeniyle geniş yüzme alanı ister.','[["Yetişkin boy", "12 cm"], ["Sıcaklık", "20–27 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "150 L"], ["Huy", "Barışçıl, aktif sürü"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçıcı"], ["Özellikler", "Sürü Balığı, Nadir Tür"]]'::jsonb,array['dawkinsia arulius','arulius barb','arulius','longfin barb']::text[],true,'published'),
('rasbora-borapetensis','Kırmızı Kuyruklu Rasbora','Rasbora borapetensis','sazangiller','fish','Kolay','Barışçıl, sürü balığı','Gümüş gövdesindeki siyah çizgi ve kırmızı kuyruk tabanıyla tanınır. Dayanıklı, hareketli ve barışçıl bir sürü balığıdır.','[["Yetişkin boy", "5 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "60 L"], ["Huy", "Barışçıl, sürü balığı"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçıcı"], ["Özellikler", "Sürü Balığı, Dayanıklı"]]'::jsonb,array['kırmızı kuyruklu rasbora','rasbora borapetensis','blackline rasbora','red tail rasbora','borapetensis']::text[],false,'published'),
('rasbora-trilineata','Scissortail Rasbora','Rasbora trilineata','sazangiller','fish','Kolay','Barışçıl, aktif sürü','Makas hareketini andıran siyah-beyaz kuyruk deseniyle tanınan aktif bir rasboradır. Uzun akvaryum ve kalabalık sürü tercih eder.','[["Yetişkin boy", "13 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "150 L"], ["Huy", "Barışçıl, aktif sürü"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçıcı"], ["Özellikler", "Sürü Balığı, Aktif"]]'::jsonb,array['rasbora trilineata','scissortail rasbora','makas kuyruk rasbora','trilineata']::text[],false,'published'),
('rasbora-einthovenii','Brilliant Rasbora','Rasbora einthovenii','sazangiller','fish','Orta','Barışçıl, sürü balığı','Koyu yatay çizgisi ve metalik gövdesiyle zarif bir sürü balığıdır. Yumuşak-asidik, bitkili akvaryumlara uygundur.','[["Yetişkin boy", "9 cm"], ["Sıcaklık", "23–28 °C"], ["pH", "5.0–7.0"], ["Min. akvaryum", "100 L"], ["Huy", "Barışçıl, sürü balığı"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçıcı"], ["Özellikler", "Sürü Balığı, Siyah Su"]]'::jsonb,array['rasbora einthovenii','brilliant rasbora','einthovenii','black stripe rasbora']::text[],true,'published'),
('trigonostigma-espei','Lambchop Rasbora','Trigonostigma espei','sazangiller','fish','Kolay','Barışçıl, sürü balığı','Bakır-turuncu gövdesindeki kuzu pirzolası biçimli siyah lekeyle tanınır. Küçük, sakin ve bitkili topluluk akvaryumlarına uygundur.','[["Yetişkin boy", "4 cm"], ["Sıcaklık", "23–28 °C"], ["pH", "5.5–7.5"], ["Min. akvaryum", "40 L"], ["Huy", "Barışçıl, sürü balığı"], ["Beslenme", "Omnivor"], ["Üreme", "Yaprak altına yumurta"], ["Özellikler", "Nano, Sürü Balığı"]]'::jsonb,array['trigonostigma espei','lambchop rasbora','espei rasbora','espei']::text[],false,'published'),
('trigonostigma-hengeli','Glowlight Rasbora','Trigonostigma hengeli','sazangiller','fish','Kolay','Barışçıl, sürü balığı','İnce turuncu ışık çizgisi ve siyah yan lekesiyle zarif bir nano sürü balığıdır. Bitkili ve hafif asidik tanklarda iyi görünür.','[["Yetişkin boy", "3,5 cm"], ["Sıcaklık", "23–28 °C"], ["pH", "5.0–7.5"], ["Min. akvaryum", "40 L"], ["Huy", "Barışçıl, sürü balığı"], ["Beslenme", "Omnivor"], ["Üreme", "Yaprak altına yumurta"], ["Özellikler", "Nano, Sürü Balığı"]]'::jsonb,array['trigonostigma hengeli','hengels rasbora','glowlight rasbora','hengeli']::text[],false,'published'),
('boraras-merah','Phoenix Rasbora','Boraras merah','sazangiller','fish','Orta','Barışçıl, sürü balığı','Kırmızı-turuncu gövdesi ve koyu yan lekeleriyle çok küçük bir sürü balığıdır. Stabil, yumuşak ve asidik su ister.','[["Yetişkin boy", "2 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "4.0–7.0"], ["Min. akvaryum", "30 L"], ["Huy", "Barışçıl, sürü balığı"], ["Beslenme", "Mikro omnivor"], ["Üreme", "Yumurta saçıcı"], ["Özellikler", "Nano, Siyah Su"]]'::jsonb,array['boraras merah','phoenix rasbora','merah','dwarf rasbora']::text[],true,'published'),
('boraras-urophthalmoides','Exclamation Point Rasbora','Boraras urophthalmoides','sazangiller','fish','Orta','Barışçıl, sürü balığı','Yanındaki ünlem işaretini andıran koyu desenle tanınan minik bir Boraras türüdür. Kalabalık sürü ve sakin nano tank uygundur.','[["Yetişkin boy", "2 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "5.0–7.0"], ["Min. akvaryum", "30 L"], ["Huy", "Barışçıl, sürü balığı"], ["Beslenme", "Mikro omnivor"], ["Üreme", "Yumurta saçıcı"], ["Özellikler", "Nano, Sürü Balığı"]]'::jsonb,array['boraras urophthalmoides','exclamation point rasbora','urophthalmoides','dwarf rasbora']::text[],true,'published'),
('danio-margaritatus','Galaxy Rasbora / CPD','Danio margaritatus','sazangiller','fish','Orta','Barışçıl, sosyal','İnci benekli gövdesi ve kırmızı-siyah yüzgeçleriyle çok popüler küçük bir sazangildir. Yoğun bitkili, serin-tropikal tanklarda iyi gelişir.','[["Yetişkin boy", "2,5 cm"], ["Sıcaklık", "20–26 °C"], ["pH", "6.5–7.5"], ["Min. akvaryum", "40 L"], ["Huy", "Barışçıl, sosyal"], ["Beslenme", "Mikro omnivor"], ["Üreme", "Yumurta saçıcı"], ["Özellikler", "Nano, Renkli"]]'::jsonb,array['galaxy rasbora / cpd','danio margaritatus','galaxy rasbora','celestial pearl danio','cpd']::text[],false,'published'),
('devario-aequipinnatus','Dev Danio','Devario aequipinnatus','sazangiller','fish','Kolay','Barışçıl, çok aktif','Hızlı yüzen, iri ve çok aktif bir sürü balığıdır. Uzun akvaryum ve güçlü oksijenlendirme tercih eder.','[["Yetişkin boy", "10 cm"], ["Sıcaklık", "20–27 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "150 L"], ["Huy", "Barışçıl, çok aktif"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçıcı"], ["Özellikler", "Sürü Balığı, Aktif"]]'::jsonb,array['devario aequipinnatus','giant danio','dev danio','aequipinnatus']::text[],false,'published'),
('danio-choprae','Glowlight Danio','Danio choprae','sazangiller','fish','Orta','Barışçıl, aktif sürü','Turuncu yatay çizgileri ve mavi tonlarıyla küçük fakat çok renkli bir daniodur. Akıntılı, oksijenli ve grup hâlinde bakım uygundur.','[["Yetişkin boy", "4 cm"], ["Sıcaklık", "20–26 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "60 L"], ["Huy", "Barışçıl, aktif sürü"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçıcı"], ["Özellikler", "Renkli, Sürü Balığı"]]'::jsonb,array['danio choprae','glowlight danio','choprae','orange fin danio']::text[],false,'published'),
('microdevario-kubotai','Neon Yeşil Rasbora','Microdevario kubotai','sazangiller','fish','Orta','Barışçıl, sürü balığı','Neon yeşil gövdesiyle dikkat çeken küçük ve çok aktif bir sürü balığıdır. Bitkili tanklarda koyu fon üzerinde belirginleşir.','[["Yetişkin boy", "3 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "40 L"], ["Huy", "Barışçıl, sürü balığı"], ["Beslenme", "Mikro omnivor"], ["Üreme", "Yumurta saçıcı"], ["Özellikler", "Nano, Neon Yeşil"]]'::jsonb,array['neon yeşil rasbora','microdevario kubotai','kubotai rasbora','neon green rasbora','kubotai']::text[],false,'published'),
('tanichthys-albonubes','White Cloud Mountain Minnow','Tanichthys albonubes','sazangiller','fish','Kolay','Barışçıl, sürü balığı','Serin suya dayanıklı, kırmızı yüzgeçli küçük bir sürü balığıdır. Isıtıcısız uygun iç mekân akvaryumlarında da bakılabilir.','[["Yetişkin boy", "4 cm"], ["Sıcaklık", "16–24 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "50 L"], ["Huy", "Barışçıl, sürü balığı"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçıcı"], ["Özellikler", "Serin Su, Sürü Balığı"]]'::jsonb,array['white cloud mountain minnow','tanichthys albonubes','white cloud','beyaz bulut balığı','mountain minnow']::text[],false,'published'),
('tanichthys-albonubes-gold','Altın White Cloud','Tanichthys albonubes ''Gold''','sazangiller','fish','Kolay','Barışçıl, sürü balığı','White Cloud Mountain Minnow''un altın renkli akvaryum formudur. Türle aynı şekilde serin, temiz ve oksijenli suyu tercih eder.','[["Yetişkin boy", "4 cm"], ["Sıcaklık", "16–24 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "50 L"], ["Huy", "Barışçıl, sürü balığı"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçıcı"], ["Özellikler", "Serin Su, Altın Form"]]'::jsonb,array['gold white cloud','tanichthys albonubes','golden mountain minnow','altın white cloud']::text[],false,'published'),
('balantiocheilos-melanopterus','Bala Shark','Balantiocheilos melanopterus','sazangiller','fish','Orta','Barışçıl, çok aktif sürü','Köpekbalığı biçimli gövdesiyle tanınan fakat barışçıl olan çok iri bir sazangildir. Sürü ve yüzme alanı ihtiyacı nedeniyle dev akvaryum gerektirir.','[["Yetişkin boy", "35 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "700 L"], ["Huy", "Barışçıl, çok aktif sürü"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçıcı"], ["Özellikler", "İri Yapılı, Sürü Balığı"]]'::jsonb,array['bala shark','balantiocheilos melanopterus','silver shark','bala köpekbalığı']::text[],false,'published'),
('crossocheilus-oblongus','Siyam Yosun Yiyici','Crossocheilus oblongus','sazangiller','fish','Kolay','Barışçıl, aktif','Alg tüketimi ve aktif yüzüşüyle tanınan sazangildir. Gerçek SAE''nin benzer ticari türlerden ayrılması önemlidir.','[["Yetişkin boy", "15 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "120 L"], ["Huy", "Barışçıl, aktif"], ["Beslenme", "Omnivor, alg ağırlıklı"], ["Üreme", "Yumurta saçıcı"], ["Özellikler", "Alg Yiyici, Aktif"]]'::jsonb,array['crossocheilus oblongus','siamese algae eater','sae','siyam yosun yiyici']::text[],false,'published'),
('epalzeorhynchos-kalopterum','Flying Fox','Epalzeorhynchos kalopterum','sazangiller','fish','Orta','Yarı agresif, bölgeci','Siyah yatay çizgisi ve yüzgeç kenarlarıyla tanınan aktif dip-orta seviye sazangildir. Erişkinlerde türdeşlerine karşı bölgecilik artabilir.','[["Yetişkin boy", "15 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "120 L"], ["Huy", "Yarı agresif, bölgeci"], ["Beslenme", "Omnivor, alg katkılı"], ["Üreme", "Yumurta saçıcı"], ["Özellikler", "Alg Yiyici, Bölgeci"]]'::jsonb,array['epalzeorhynchos kalopterum','flying fox','uçan tilki balığı','kalopterum']::text[],false,'published'),
('epalzeorhynchos-bicolor','Red Tail Black Shark','Epalzeorhynchos bicolor','sazangiller','fish','Orta','Bölgeci, yarı agresif','Simsiyah gövdesi ve parlak kırmızı kuyruğuyla çok karakteristik bir sazangildir. Erişkinlerde dip bölgesini sert biçimde savunabilir.','[["Yetişkin boy", "15 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "150 L"], ["Huy", "Bölgeci, yarı agresif"], ["Beslenme", "Omnivor, alg katkılı"], ["Üreme", "Yumurta saçıcı"], ["Özellikler", "Bölgeci, Renkli"]]'::jsonb,array['epalzeorhynchos bicolor','red tail black shark','kırmızı kuyruklu siyah köpekbalığı','bicolor']::text[],false,'published'),
('epalzeorhynchos-frenatum','Rainbow Shark','Epalzeorhynchos frenatum','sazangiller','fish','Orta','Bölgeci, yarı agresif','Koyu gövdesi ve kırmızı yüzgeçleriyle dikkat çeker. Dip bölgesinde benzer şekilli balıklara karşı bölgeci olabilir.','[["Yetişkin boy", "15 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "150 L"], ["Huy", "Bölgeci, yarı agresif"], ["Beslenme", "Omnivor, alg katkılı"], ["Üreme", "Yumurta saçıcı"], ["Özellikler", "Bölgeci, Renkli"]]'::jsonb,array['epalzeorhynchos frenatum','rainbow shark','ruby shark','gökkuşağı shark']::text[],false,'published'),
('barbodes-everetti','Clown Barb','Barbodes everetti','sazangiller','fish','Orta','Barışçıl, aktif','Turuncu-kırmızı gövdesindeki düzensiz koyu lekelerle dikkat çeken iri bir barb türüdür. Grup hâlinde geniş akvaryum ister.','[["Yetişkin boy", "15 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "180 L"], ["Huy", "Barışçıl, aktif"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçıcı"], ["Özellikler", "Sürü Balığı, Benekli"]]'::jsonb,array['barbodes everetti','clown barb','everetts barb','everetti']::text[],true,'published'),
('barbodes-lateristriga','Spanner Barb','Barbodes lateristriga','sazangiller','fish','Orta','Barışçıl, aktif sürü','Yan gövdedeki anahtar/spanner benzeri koyu desenle tanınan iri ve aktif bir barb türüdür. Geniş yüzme alanı ister.','[["Yetişkin boy", "18 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "200 L"], ["Huy", "Barışçıl, aktif sürü"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçıcı"], ["Özellikler", "İri Barb, Sürü Balığı"]]'::jsonb,array['barbodes lateristriga','spanner barb','t barb','lateristriga']::text[],true,'published')
